def resolve(path, cwd, links):
    # Validate inputs
    if not isinstance(cwd, str) or not cwd.startswith('/'):
        return None
    if not isinstance(path, str):
        return None
    if not isinstance(links, dict):
        return None

    # Start with cwd if path is relative
    if path.startswith('/'):
        current = '/'
        components = path.split('/')[1:]  # Skip empty first element
    else:
        current = cwd
        components = path.split('/')[1:] if path.startswith('/') else path.split('/')

    link_count = 0
    max_links = 8

    i = 0
    while i < len(components):
        comp = components[i]
        i += 1

        # Skip empty components and '.'
        if comp == '' or comp == '.':
            continue

        # Handle '..'
        if comp == '..':
            if current != '/':
                # Move to parent directory
                current = current.rsplit('/', 1)[0]
                if current == '':
                    current = '/'
            # If already at '/', stay at '/'
            continue

        # Append component to current path
        if current == '/':
            candidate = '/' + comp
        else:
            candidate = current + '/' + comp

        # Check if this is a symlink
        if candidate in links:
            link_count += 1
            if link_count > max_links:
                return None

            target = links[candidate]

            # Parse the target
            if target.startswith('/'):
                # Absolute target
                current = '/'
                new_components = target.split('/')[1:]  # Skip empty first element
            else:
                # Relative target - relative to the directory containing the link
                if candidate == '/':
                    current = '/'
                else:
                    current = candidate.rsplit('/', 1)[0]
                new_components = target.split('/')

            # Insert remaining original components after new components
            components = new_components + components[i:]
            i = 0
        else:
            # Not a symlink, just move to this path
            current = candidate

    # Remove trailing slash, except for '/'
    if current != '/' and current.endswith('/'):
        current = current.rstrip('/')

    return current

